package com.campusevents.ui;
import com.campusevents.model.*;import com.campusevents.service.*;import javax.swing.*;import javax.swing.table.*;import java.awt.*;
public class StudentFrame extends JFrame {private final Student student;private final EventService es=new EventService();private final RegistrationService rs=new RegistrationService();private final DefaultTableModel em=new DefaultTableModel(new String[]{"ID","com.campusevents.model.Event","Category","Date","Venue","Seats","Organizer"},0){public boolean isCellEditable(int r,int c){return false;}};private final DefaultTableModel rm=new DefaultTableModel(new String[]{"Registration ID","com.campusevents.model.Event","Date","Venue","Status","Registered"},0){public boolean isCellEditable(int r,int c){return false;}};private final JTable et=new JTable(em),rt=new JTable(rm);private final JTextField search=new JTextField(16);private final JComboBox<String> cat=new JComboBox<>();public StudentFrame(Student s){super("Student dashboard - "+s.getName());student=s;setDefaultCloseOperation(EXIT_ON_CLOSE);setSize(1050,650);setLocationRelativeTo(null);JPanel root=new JPanel(new BorderLayout(8,8));root.setBorder(BorderFactory.createEmptyBorder(15,15,15,15));JLabel heading=new JLabel("Welcome, "+s.getName());heading.setFont(new Font("SansSerif",Font.BOLD,23));JButton logout=new JButton("Log out");JPanel top=new JPanel(new BorderLayout());top.add(heading,BorderLayout.WEST);top.add(logout,BorderLayout.EAST);root.add(top,BorderLayout.NORTH);JTabbedPane tabs=new JTabbedPane();tabs.addTab("Discover events",discover());tabs.addTab("My registrations",myRegs());root.add(tabs);setContentPane(root);logout.addActionListener(e->{dispose();new LoginFrame().setVisible(true);});loadEvents();}private JPanel discover(){JPanel p=new JPanel(new BorderLayout(8,8));JPanel filter=new JPanel();filter.add(new JLabel("Search"));filter.add(search);filter.add(new JLabel("Category"));try{for(String s:es.categories())cat.addItem(s);}catch(Exception ignored){}filter.add(cat);JButton find=new JButton("Find");filter.add(find);p.add(filter,BorderLayout.NORTH);p.add(new JScrollPane(et));JPanel buttons=new JPanel();JButton detail=new JButton("Details"),register=new JButton("Register");buttons.add(detail);buttons.add(register);p.add(buttons,BorderLayout.SOUTH);find.addActionListener(e->loadEvents());cat.addActionListener(e->loadEvents());detail.addActionListener(e->details());register.addActionListener(e->register());return p;}private JPanel myRegs(){JPanel p=new JPanel(new BorderLayout());p.add(new JScrollPane(rt));JPanel b=new JPanel();JButton refresh=new JButton("Refresh"),cancel=new JButton("Cancel selected");b.add(refresh);b.add(cancel);p.add(b,BorderLayout.SOUTH);refresh.addActionListener(e->loadRegs());cancel.addActionListener(e->cancel());return p;}private Integer selected(){int r=et.getSelectedRow();return r<0?null:(Integer)em.getValueAt(et.convertRowIndexToModel(r),0);}private void loadEvents(){try{em.setRowCount(0);for(com.campusevents.model.Event e:es.search(search.getText(),(String)cat.getSelectedItem()))em.addRow(new Object[]{e.id(),e.title(),e.category(),e.date(),e.venue(),e.available(),e.organizer()});}catch(Exception e){error(e);}}private void loadRegs(){try{rm.setRowCount(0);for(String[] r:rs.mine(student))rm.addRow(r);}catch(Exception e){error(e);}}private void details(){Integer id=selected();if(id==null){warn("Select an event.");return;}try{com.campusevents.model.Event e=es.get(id);JOptionPane.showMessageDialog(this,e.title()+"\n\n"+e.description()+"\nCategory: "+e.category()+"\nOrganizer: "+e.organizer()+"\nDate/time: "+e.date()+" "+e.start()+"-"+e.end()+"\nVenue: "+e.venue()+"\nDeadline: "+e.deadline()+"\nSeats available: "+e.available()+"/"+e.capacity());}catch(Exception x){error(x);}}private void register(){Integer id=selected();if(id==null){warn("Select an event.");return;}try{String[] a=rs.register(student,id).split("\\|");JOptionPane.showMessageDialog(this,"Registration: "+a[0]+"\nStatus: "+a[1]);loadEvents();loadRegs();}catch(Exception e){error(e);}}private void cancel(){int r=rt.getSelectedRow();if(r<0){warn("Select a registration.");return;}try{rs.cancel(student,(String)rm.getValueAt(rt.convertRowIndexToModel(r),0));JOptionPane.showMessageDialog(this,"Cancelled. Waitlist promotion was processed if applicable.");loadRegs();loadEvents();}catch(Exception e){error(e);}}private void warn(String s){JOptionPane.showMessageDialog(this,s);}private void error(Exception e){JOptionPane.showMessageDialog(this,e.getMessage(),"Error",JOptionPane.ERROR_MESSAGE);}}
